-- NOYA commercial library: 11 products (internal sales frameworks, not public) and 13 playbooks.
-- Cold-email rules baked into every template (what gets replies at this level):
--   * subject: 2–5 words, about THEM (their event / property / project), no hype, no "partnership opportunity";
--   * line 1: the specific trigger, proving we noticed something real — never "I hope this finds you well";
--   * line 2: the operational problem that trigger creates for them (their words, not ours);
--   * line 3: one concrete proof of NOYA on the ground (Egypt team, partners, a comparable delivery);
--   * line 4: one small, specific offer — never a menu of 20 services;
--   * close: one low-friction question (a 15-minute call, or "who handles X?") — never two asks;
--   * under ~90 words, plain text, no attachments, no links on the first touch;
--   * follow-ups add something new each time (a detail, an idea, a referral ask) and stop after the third.
-- Placeholders: {{first_name}} {{company}} {{event}} {{event_date}} {{destination}} {{trigger_detail}} {{proof}}.
-- Sign-off everywhere: Adam Elshazly · Founder, NOYA Concierge · noyaconcierge.com

insert into public.commercial_products (code, name, summary, owner_role, target_segments, ideal_client, buyer_roles, trigger_events, client_problems,
  solution, included_services, proof_points, partner_types, outreach_angles, email_template, dm_template, call_points, objections, proposal_template,
  follow_up_sequence, upsells, recurring_potential)
values
('EVENT_CONCIERGE_DESK', 'NOYA Event Concierge Desk',
