-- Default follow-up sequence for playbooks = the lead product's sequence (kept in one place).
update public.commercial_playbooks p set follow_up_sequence = coalesce((select follow_up_sequence from commercial_products where code = p.product_codes[1]), '[]')
 where follow_up_sequence = '[]'::jsonb;
